const themes={clear:{name:'Clear',tag:'01 / REKOMENDOWANY KIERUNEK',title:'Mniej formalności. Więcej możliwości.',desc:'Czysta biel, głęboki granat i precyzyjny błękit. Czytelny portal, który od pierwszego ekranu buduje zaufanie.',colors:['#0F2A47','#2563EB','#EFF5FD','#FFFFFF'],labels:['Granat / marka','Błękit / akcent','Błękitna mgła / tło','Biel / powierzchnie'],heading:'Manrope',body:'Manrope',hero:'Dobra praca.<br><em>Bliżej, niż myślisz.</em>',aside:'Bez CV.',asideText:'Twoje umiejętności mówią więcej niż idealny dokument.',brand:'Przejrzystość, która daje pewność.',rationale:'Najbliższy produktowi z repozytorium. Zachowuje rozpoznawalny granat i błękit, porządkuje hierarchię oraz rozjaśnia panele. Dobry wybór dla szerokiej grupy kandydatów i pracodawców.',geometry:'Zaokrąglenia 12 px. Cienkie obrysy. Rytm 8 px. Nagłówki zwarte, formularze przestronne.',voice:'Prosto i życzliwie. Jedno zdanie — jedna informacja. Wynagrodzenie i lokalizacja zawsze łatwe do znalezienia.'},nord:{name:'Nord',tag:'02 / KIERUNEK REDAKCYJNY',title:'Nowy rozdział zaczyna się tutaj.',desc:'Biel, głęboka zieleń i elegancki krój szeryfowy. Bardziej ludzka, spokojna marka z własnym charakterem.',colors:['#193F35','#176453','#F1F5F1','#FFFFFF'],labels:['Leśna zieleń / tekst','Zieleń / akcje','Jasna szarość / tło','Biel / powierzchnie'],heading:'DM Serif Display',body:'DM Sans',hero:'Twoje umiejętności.<br><em>Nowe możliwości.</em>',aside:'Po swojemu.',asideText:'Znajdź pracę, która pasuje do Twojego doświadczenia i planów.',brand:'Praca to część Twojej historii.',rationale:'Najbardziej charakterystyczny i spokojny kierunek. Szeryf pojawia się w nagłówkach; oferty, filtry i formularze pozostają w bardzo czytelnym kroju bezszeryfowym.',geometry:'Zaokrąglenia 4 px. Więcej oddechu. Rytm 8 px. Delikatne linie zamiast cieni. Duże, redakcyjne nagłówki.',voice:'Spokojnie, konkretnie i z szacunkiem. Skupiamy się na doświadczeniu człowieka, bez języka korporacyjnej rekrutacji.'},signal:{name:'Signal',tag:'03 / KIERUNEK WYRAZISTY',title:'Konkretna praca. Wyraźny kierunek.',desc:'Biel, grafit i świeży limonkowy akcent. Zdecydowana typografia, oszczędna geometria i oferty na pierwszym planie.',colors:['#242821','#E6FA65','#F5F7ED','#FFFFFF'],labels:['Grafit / tekst','Limonka / akcje','Jasna szarość / tło','Biel / powierzchnie'],heading:'Manrope',body:'DM Sans',hero:'Twoja praca.<br><em>Twój następny krok.</em>',aside:'Do rzeczy.',asideText:'Jasne warunki. Widoczna stawka. Prosta droga do pracodawcy.',brand:'Umiejętności. Możliwości. Start.',rationale:'Najmocniejsza rozpoznawalność. Limonka wyróżnia najważniejsze akcje, a grafit zapewnia czytelność. Układ jest bardziej geometryczny i zwarty.',geometry:'Proste narożniki. Mocniejsze linie. Rytm 8 px. Duże nagłówki i kontrastowe akcje. Bez dekoracyjnych gradientów.',voice:'Krótko i bez nadęcia. Mówimy o warunkach, umiejętnościach i kolejnym kroku. Energia bez presji.'}};
const jobs=[{id:1,title:'Operator wózka widłowego',company:'Northline Logistics',city:'Antwerpia',salary:'17–20 €',period:'brutto / godz.',category:'Logistyka',initials:'NL',tags:['Umowa o pracę','Zakwaterowanie'],desc:'Obsługa wózka widłowego, kompletowanie zamówień i współpraca z zespołem magazynu.'},{id:2,title:'Elektryk przemysłowy',company:'Voltwerk Belgium',city:'Gandawa',salary:'21–25 €',period:'brutto / godz.',category:'Technika',initials:'VB',tags:['Pełny etat','Transport'],desc:'Montaż i konserwacja instalacji elektrycznych w zakładzie produkcyjnym.'},{id:3,title:'Pracownik produkcji',company:'Forma Foods',city:'Bruksela',salary:'16–18 €',period:'brutto / godz.',category:'Produkcja',initials:'FF',tags:['Bez doświadczenia','Pełny etat'],desc:'Praca przy pakowaniu produktów i kontroli jakości w zespole produkcyjnym.'},{id:4,title:'Monter konstrukcji',company:'Buildpoint',city:'Antwerpia',salary:'20–24 €',period:'brutto / godz.',category:'Budownictwo',initials:'BP',tags:['Umowa o pracę','Zakwaterowanie'],desc:'Montaż konstrukcji na podstawie dokumentacji technicznej, praca w stałym zespole.'}];
let theme='clear',view='home',query='',city='',categories=[],detailId=1;const saved=new Set();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo=()=>theme==='clear'?'<span class="logo"><span class="word">pracuj<span class="logo-dot">.</span><span class="suffix">be</span></span></span>':'<span class="logo"><span class="mark" aria-hidden="true">p</span><span>pracuj<span class="suffix">.be</span></span></span>';
const button=(label,target,cls='btn')=>`<button class="${cls}" data-go="${target}">${label}</button>`;
function nav(){return `<header class="nav"><a href="#home" data-go="home" aria-label="Pracuj.be — strona główna">${logo()}</a><nav class="navlinks" aria-label="Pracuj.be">${button('Oferty pracy','jobs','navlink')}${button('Dla pracodawców','employer','navlink')}</nav><div class="account"><span>PL</span>${button('Moje konto','candidate','navlink')}${button('Panel pracodawcy','employer')}</div></header>`;}
const footer=()=>`<footer class="site-footer"><span>pracuj.be · Praca w Belgii, po prostu.</span><span>Podgląd koncepcji · firmy, osoby i oferty są przykładowe</span></footer>`;
function search(){return `<form class="search" id="search"><label>Jakiej pracy szukasz?<input name="query" placeholder="Stanowisko lub słowo kluczowe" value="${esc(query)}"></label><label>Gdzie chcesz pracować?<input name="city" placeholder="Miasto w Belgii" value="${esc(city)}"></label><button class="btn" type="submit">Szukaj pracy <span aria-hidden="true">↗</span></button></form>`;}
function jobCard(j,compact=false){return `<article class="job"><span class="company-icon">${j.initials}</span><div class="jobmain"><h3><a href="#detail-${j.id}" data-detail="${j.id}">${j.title}</a></h3><p>${j.company} · ${j.city}</p>${compact?'':j.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="jobright"><strong>${j.salary}</strong><small>${j.period}</small></div><button class="save" data-save="${j.id}" aria-pressed="${saved.has(j.id)}" aria-label="${saved.has(j.id)?'Usuń zapisaną ofertę':'Zapisz ofertę'}: ${j.title}">${saved.has(j.id)?'★':'☆'}</button></article>`;}
function home(){const t=themes[theme];return `${nav()}<main><section class="hero"><div class="hero-head"><div><div class="hero-kicker">Praca w Belgii. Na Twoich zasadach.</div><h1>${t.hero}</h1><p>Znajdź ofertę dla siebie. Pokaż, co potrafisz — prosty profil zawodowy wystarczy, żeby zacząć.</p></div><aside class="hero-aside"><strong>${t.aside}</strong><p>${t.asideText}</p>${button('Poznaj swój profil','candidate','text-link')}</aside></div>${search()}<div class="popular"><span>Popularne:</span>${['Logistyka','Produkcja','Budownictwo','Technika'].map(x=>`<button data-category="${x}">${x}</button>`).join('')}</div></section><div class="trust"><span>Profil zawodowy zamiast CV</span><span>Warunki pracy na pierwszym planie</span><span>Oferty w całej Belgii</span></div><section class="section"><div class="section-head"><div><h2>Twój następny krok</h2><p>Poznaj najnowsze oferty pracy.</p></div>${button('Wszystkie oferty ↗','jobs','text-link')}</div>${jobs.slice(0,3).map(j=>jobCard(j,true)).join('')}</section><section class="cta-band"><div><h2>Masz umiejętności. Daj się znaleźć.</h2><p>Uzupełnij profil i otrzymuj propozycje od pracodawców.</p></div>${button('Zobacz profil kandydata','candidate')}</section></main>${footer()}`;}
function jobList(){const filtered=jobs.filter(j=>(j.title+' '+j.company+' '+j.category).toLowerCase().includes(query.toLowerCase())&&j.city.toLowerCase().includes(city.toLowerCase())&&(!categories.length||categories.includes(j.category)));return `${nav()}<main><header class="page-title"><span class="crumb">Strona główna / Oferty pracy</span><h1>Znajdź swoje miejsce.</h1>${search()}</header><div class="listing"><aside class="filters"><h3>Branża</h3>${['Logistyka','Produkcja','Budownictwo','Technika'].map(x=>`<label><input type="checkbox" data-filter="${x}" ${categories.includes(x)?'checked':''}>${x}</label>`).join('')}<div class="filter-extra"><h3>Lokalizacja</h3><select id="city-filter" aria-label="Lokalizacja"><option value="">Cała Belgia</option ${city==='Antwerpia'?'selected':''}>Antwerpia</option ${city==='Bruksela'?'selected':''}>Bruksela</option ${city==='Gandawa'?'selected':''}>Gandawa</option></select></div><button class="text-link" id="reset">Wyczyść filtry</button></aside><section><div class="results-top"><strong>Liczba ofert: ${filtered.length}</strong><span>Dane demonstracyjne</span></div>${filtered.length?filtered.map(j=>jobCard(j)).join(''):'<div class="empty"><h3>Nie ma ofert dla tych filtrów.</h3><p>Zmień stanowisko lub wybierz inne miasto.</p></div>'}</section></div></main>${footer()}`;}
function sidebar(employer){return `<aside class="sidebar"><div class="side-person"><span class="company-icon">${employer?'NL':'MK'}</span><strong>${employer?'Northline Logistics':'Michał Kowalski'}</strong><span>${employer?'Panel pracodawcy':'Profil kandydata'}</span></div><small>TWOJE MIEJSCE</small><span class="side-item active">Podsumowanie</span><span class="side-item">${employer?'Oferty pracy':'Mój profil'}</span><span class="side-item">${employer?'Kandydaci':'Moje aplikacje'}<b>${employer?'12':'4'}</b></span><span class="side-item">Wiadomości <b>2</b></span><span class="side-item">${employer?'Firma i pakiet':'Zapisane oferty'}</span></aside>`;}
function stats(items){return `<div class="stats">${items.map(([a,b,c])=>`<article class="stat"><span>${a}</span><strong>${b}</strong><small>${c}</small></article>`).join('')}</div>`;}
function candidate(){return `${nav()}<main class="dashboard">${sidebar(false)}<div class="dash-content"><span class="eyebrow">TWÓJ NASTĘPNY KROK</span><h1>Dzień dobry, Michale.</h1><p class="dash-intro">Twoje aplikacje, propozycje i możliwości — w jednym miejscu.</p><div class="notice"><div><strong>Nowa propozycja od Northline Logistics</strong><p>Operator wózka widłowego · Antwerpia · 17–20 € brutto / godz.</p></div><button class="btn" data-detail="1">Zobacz ofertę</button></div>${stats([['Moje aplikacje','4','1 zaproszenie na rozmowę'],['Propozycje pracy','2','1 nowa propozycja'],['Zapisane oferty',String(saved.size),'W tym podglądzie']])}<div class="dash-grid"><section class="panel"><h2>Oferty dla Ciebie</h2><p>Na podstawie Twoich umiejętności.</p>${jobs.slice(0,2).map(j=>jobCard(j,true)).join('')}${button('Zobacz wszystkie oferty','jobs','text-link')}</section><section class="panel"><h2>Twój profil · 80%</h2><p>Jeszcze jeden krok, by lepiej pokazać swoje doświadczenie.</p><div class="progress" role="progressbar" aria-valuenow="80" aria-valuemin="0" aria-valuemax="100" aria-label="Uzupełnienie profilu"><span></span></div><ul class="checklist"><li>Dane podstawowe</li><li>Doświadczenie zawodowe</li><li>Umiejętności</li><li>Znajomość języków</li><li>Dodaj uprawnienia</li></ul><span class="tag">Podgląd przykładowego profilu</span></section></div></div></main>${footer()}`;}
function employer(){return `${nav()}<main class="dashboard">${sidebar(true)}<div class="dash-content"><div class="section-head"><div><span class="eyebrow">NORTHLINE LOGISTICS</span><h1>Dobry zespół zaczyna się tutaj.</h1><p class="dash-intro">Najważniejsze informacje o Twojej rekrutacji.</p></div></div>${stats([['Aktywne oferty','3','2 lokalizacje'],['Nowe aplikacje','12','Do przejrzenia'],['Zaplanowane rozmowy','4','W tym tygodniu']])}<section class="panel"><div class="section-head"><h2>Twoje oferty pracy</h2><span class="tag">Przykładowy panel</span></div><div class="table-wrap"><table><thead><tr><th>Stanowisko</th><th>Lokalizacja</th><th>Aplikacje</th><th>Status</th></tr></thead><tbody><tr><td>Operator wózka widłowego</td><td>Antwerpia</td><td>8</td><td><span class="tag">Aktywna</span></td></tr><tr><td>Pracownik magazynu</td><td>Antwerpia</td><td>3</td><td><span class="tag">Aktywna</span></td></tr><tr><td>Koordynator zmiany</td><td>Gandawa</td><td>1</td><td><span class="tag">Aktywna</span></td></tr></tbody></table></div></section><div class="dash-grid" style="margin-top:24px"><section class="panel"><h2>Najnowsze aplikacje</h2><article class="job"><span class="company-icon">MK</span><div><h3>Michał Kowalski</h3><p>Operator wózka widłowego · 3 lata doświadczenia</p><span class="tag">Nowa aplikacja</span></div></article><article class="job"><span class="company-icon">AN</span><div><h3>Anna Nowak</h3><p>Pracownik magazynu · 2 lata doświadczenia</p><span class="tag">Zaproszenie na rozmowę</span></div></article></section><section class="panel"><h2>Rekrutacja w liczbach</h2><p>Od pierwszego zgłoszenia do rozmowy.</p><div class="progress"><span style="width:100%"></span></div><p><strong>12</strong> nowych aplikacji</p><div class="progress"><span style="width:66%"></span></div><p><strong>8</strong> przejrzanych profili</p><div class="progress"><span style="width:33%"></span></div><p><strong>4</strong> zaplanowane rozmowy</p></section></div></div></main>${footer()}`;}
function brand(){const t=themes[theme];return `${nav()}<main class="brand-board"><div class="brand-hero"><div><span class="eyebrow">PRACUJ.BE / ${t.name.toUpperCase()}</span><h1>${t.brand}</h1><p>${t.rationale}</p></div><div class="brand-logo">${logo()}</div></div><div class="palette-list">${t.colors.map((c,i)=>`<div class="color-item"><div class="color-box" style="background:${c}"></div><strong>${t.labels[i]}</strong><span>${c}</span></div>`).join('')}</div><div class="brand-grid"><article><span class="eyebrow">01 / TYPOGRAFIA</span><div class="specimen">Aa Bb<br>ąęłńó</div><h3>${t.heading}</h3><p>Nagłówki: ${t.heading}.<br>Teksty i interfejs: ${t.body}.<br>Tekst podstawowy 16 px. Etykiety formularzy pozostają widoczne.</p></article><article><span class="eyebrow">02 / JĘZYK FORMY</span><h2 style="margin-top:25px">Spójny w każdym detalu.</h2><p>${t.geometry}</p><div class="brand-sample"><span class="btn">Szukaj pracy</span><span class="btn secondary">Moje konto</span></div><div class="brand-sample"><span class="tag">Nowa propozycja</span><span class="tag">Pełny etat</span></div></article><article><span class="eyebrow">03 / GŁOS MARKI</span><h2 style="margin-top:25px">„Pokaż, co potrafisz.”</h2><p>${t.voice}</p><p>„Znajdź pracę w Belgii.”<br>„Zapisz ofertę na później.”<br>„Uzupełnij swoje doświadczenie.”</p></article></div><section class="cta-band" style="margin:30px 0 0"><div><h2>Znak, który działa w małej skali.</h2><p>Litera „p” w prostej formie. Wersja pełna, sygnet i jednobarwna. Bez teczek, krawatów i uścisków dłoni.</p></div><div class="brand-sample"><span class="mark">p</span><span class="mark" style="background:#242821;color:white">p</span><span class="mark" style="background:white;color:#242821;border:1px solid #ddd">p</span></div></section><p>Na tym etapie: propozycja systemu wizualnego. Zdjęcia w przyszłej identyfikacji: autentyczne miejsca pracy i ludzie przy wykonywaniu zawodu, naturalne światło, bez inscenizowanej korporacyjnej fotografii. Kolory sukcesu, ostrzeżenia i błędu mają stałe znaczenie, niezależne od koloru marki.</p></main>${footer()}`;}
function detail(){const j=jobs.find(x=>x.id===detailId)||jobs[0];return `${nav()}<main class="detail">${button('← Wróć do ofert','jobs','text-link')}<p class="crumb">Oferty pracy / ${j.city} / ${j.category}</p><h1>${j.title}</h1><p>${j.company} · ${j.city}</p><div class="detail-columns"><section><h2>O tej pracy</h2><p>${j.desc}</p><h2>Co oferuje pracodawca</h2><ul><li>${j.salary} ${j.period}</li>${j.tags.map(x=>`<li>${x}</li>`).join('')}<li>Wprowadzenie do pracy i wsparcie zespołu</li></ul><h2>Jak wygląda aplikowanie?</h2><p>W docelowym serwisie możesz aplikować swoim profilem zawodowym. Ten podgląd pokazuje projekt interfejsu i nie wysyła aplikacji.</p></section><aside class="panel"><h2>${j.salary}</h2><p>${j.period}</p>${button('Zobacz profil kandydata','candidate')}<p>Oferta demonstracyjna.<br>Nie prowadzimy tu rekrutacji.</p></aside></div></main>${footer()}`;}
function render(){const t=themes[theme];document.getElementById('concept').className='concept '+theme;document.getElementById('direction-tag').textContent=t.tag;document.getElementById('direction-title').textContent=t.title;document.getElementById('direction-desc').textContent=t.desc;document.getElementById('swatches').innerHTML=t.colors.map(c=>`<span class="swatch" style="background:${c}" title="${c}"></span>`).join('');document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.theme===theme));document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));document.getElementById('screen').innerHTML=({home, jobs:jobList,candidate,employer,brand,detail}[view]||home)();history.replaceState(null,'',`#${theme}/${view}`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.theme){theme=b.dataset.theme;render();}else if(b.dataset.view||b.dataset.go){e.preventDefault();view=b.dataset.view||b.dataset.go;render();}else if(b.dataset.size){document.getElementById('site').classList.toggle('mobile',b.dataset.size==='mobile');document.querySelectorAll('[data-size]').forEach(x=>x.setAttribute('aria-pressed',x===b));}else if(b.dataset.detail){e.preventDefault();detailId=Number(b.dataset.detail);view='detail';render();}else if(b.dataset.save){const id=Number(b.dataset.save);saved.has(id)?saved.delete(id):saved.add(id);b.setAttribute('aria-pressed',saved.has(id));b.textContent=saved.has(id)?'★':'☆';b.setAttribute('aria-label',`${saved.has(id)?'Usuń zapisaną ofertę':'Zapisz ofertę'}: ${jobs.find(j=>j.id===id).title}`);}else if(b.dataset.category){categories=[b.dataset.category];query='';city='';view='jobs';render();}else if(b.id==='reset'){categories=[];query='';city='';render();}});
document.addEventListener('submit',e=>{if(e.target.id==='search'){e.preventDefault();const f=new FormData(e.target);query=String(f.get('query')).trim();city=String(f.get('city')).trim();view='jobs';render();}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){const x=e.target.dataset.filter;categories=e.target.checked?[...categories,x]:categories.filter(c=>c!==x);render();}if(e.target.id==='city-filter'){city=e.target.value;render();}});
const initial=location.hash.slice(1).split('/');if(themes[initial[0]])theme=initial[0];if(['home','jobs','candidate','employer','brand'].includes(initial[1]))view=initial[1];render();
